try (ExecutorService executor = Executors.newFixedThreadPool(4)) {
    for (int indeks = 0; indeks < 20; indeks++) {
        int i = indeks;
        executor.submit(() -> {
            Thread.sleep(50); // symulowane I/O - watek bezczynnie czeka
            return i;
        });
    }
} // czas calkowity ~250ms (20/4 * 50ms)

